// EERMPlayer::mTeam of the neutral start areas CMUGenerateNeutralPositions creates (players get their team index >= 0).
// Names are provisional from the creating branch.
enum EERMNeutralTeam {
    kNeutralTeamInnerNeutral = -16,  // CMUGenerateNeutralPositions: the mNumInnerNeutrals loop (mIsOuter false, ring 240) (provisional name)
    kNeutralTeamOuterNeutral = -15,  // CMUGenerateNeutralPositions: the mNumOuterNeutrals loop (mIsOuter true) (provisional name)
    kNeutralTeamMoon = -14,        // CMUGenerateNeutralPositions: the mNumMoons loop (mIsMoon true, ring 250) (provisional name)
};

// Random map object / resource kinds (EERMObject::mKind, EERMSpacingRule::mKind, the PlaceObject*/CanPlaceResource kind, mKindSpacing/mResourcePerPlayer/mResourceTerrainTexture index): InitializeMapTypes 0x1000e703 registers each script name with its kind (AddMapType("Stone", "0") ...).
enum EERMObjectKind {
    kRMObjectStone = 0,  // InitializeMapTypes 0x1000e703 AddMapType("Stone", 0)
    kRMObjectGold = 1,  // InitializeMapTypes 0x1000e703 AddMapType("Gold", 1)
    kRMObjectTree = 2,  // InitializeMapTypes 0x1000e703 AddMapType("Tree", 2)
    kRMObjectBerry = 3,  // InitializeMapTypes 0x1000e703 AddMapType("Berry", 3)
    kRMObjectAnimal = 4,  // InitializeMapTypes 0x1000e703 AddMapType("Animal", 4)
    kRMObjectFish = 5,  // InitializeMapTypes 0x1000e703 AddMapType("Fish", 5)
    kRMObjectIron = 6,  // InitializeMapTypes 0x1000e703 AddMapType("Steel", 6) and AddMapType("Iron", 6) (exe EEResourceType kResourceIron)
    kRMObjectCount = 7,  // number of kinds (mKindSpacing[7], mResourcePerPlayer[7]; CMUGenerateResources 0x1000307e loops PlaceObjects over kinds 0..6; ParseLine rejects a spacing kind >= 7) (provisional name)
};

// Random map script MapCharacteristics bits (EERandomMapData::mMapCharacteristics, copied to EEMap::mU19564C by EERandomMap.cpp:317): Default.dll InitializeMapTypes 0x1000e703 registers the script names (AddMapType); the .rmv scripts OR them (MapCharacteristics (WaterlessMap,EarthMap))
enum EERMMapCharacteristic {
    kRMMapIslandMap = 1,        // Default.dll InitializeMapTypes 0x1000e703 AddMapType("IslandMap", "1")
    kRMMapWaterlessMap = 2,     // Default.dll InitializeMapTypes 0x1000e703 AddMapType("WaterlessMap", "2")
    kRMMapPlanetsMap = 4,       // Default.dll InitializeMapTypes 0x1000e703 AddMapType("PlanetsMap", "4")
    kRMMapEarthMap = 8,         // Default.dll InitializeMapTypes 0x1000e703 AddMapType("EarthMap", "8")
    kRMMapMarsMap = 0x10,       // Default.dll InitializeMapTypes 0x1000e703 AddMapType("MarsMap", "16"); gUsingCarbon = (characteristics & kRMMapMarsMap) != 0
    kRMMapEarthOrMarsMap = kRMMapEarthMap | kRMMapMarsMap,  // kRMMapEarthMap | kRMMapMarsMap (EERandomMap.cpp:214, CMU Map Generator.cpp:875)
};

